  add('T02','get_project_overview','项目概况','读取项目档案、计数、成员及已存配置状态，不刷新 Google。',1,z.object({project_id:Id,include:z.array(z.enum(['profile','counts','members','data_status'])).min(1).max(4).optional()}).strict(),overview);
  add('T03','list_articles','文章台账','分页读取站内或外链文章元数据，不计算绩效。',1,z.object({...articleFields,...pageSchema.shape,sort:z.enum(['published_at','created_at','title','url','sort_order']).default('published_at'),direction:Direction.default('desc'),include_url_history:z.boolean().default(false)}).strict(),async(input,actor)=>{articleChecks(input);await checkedScope(actor,input);if(input.sort==='sort_order' && (input.article_type!=='internal' || input.project_ids?.length!==1))fail('VALIDATION_ERROR','sort_order 必须指定单个站内项目');if(input.article_type==='external' && input.include_url_history)fail('VALIDATION_ERROR','外链不支持 url_history');const r=await q.articles(actor,input);const out=listResult(input,r,a=>articleDTO(a,input.article_type));if(input.include_url_history && r.rows.length){const history=budget(await q.history(actor,{...input,article_ids:r.rows.map(a=>a.id)}),2000,'历史地址');for(const a of out.data.items)a.url_history=history.filter(h=>h.article_id===a.ref.article_id).map(h=>({url:h.url,changed_at:h.url_changed_at}));}return out;});

